import sys
import json
import re
import math
from collections import defaultdict

# 常见英文停用词集合（部分示例，实际使用时可扩展）
STOP_WORDS = {
    "a", "an", "the", "is", "are", "was", "were", "be", "been", "being",
    "have", "has", "had", "do", "does", "did", "but", "if", "or", "and",
    "not", "no", "nor", "so", "as", "at", "by", "for", "from", "of",
    "on", "to", "with", "in", "into", "onto", "than", "that", "this",
    "these", "those", "it", "its", "he", "she", "they", "we", "you",
    "i", "me", "my", "your", "his", "her", "them", "our", "us",
    "am", "would", "could", "should", "will", "can", "may", "shall",
    "here", "there", "where", "when", "why", "how", "all", "each",
    "every", "both", "few", "more", "most", "other", "some", "such",
    "only", "own", "same", "too", "very", "just", "about", "above",
    "after", "again", "against", "while", "between", "through", "during",
    "before", "below", "up", "down", "out", "off", "over", "under",
    "further", "then", "once", "now", "new", "also", "like"
}

def tokenize(text: str):
    """ 小写化并按非字母字符分词，返回有效词语列表（已去除停用词） """
    tokens = re.findall(r'[a-zA-Z]+', text.lower())
    return [w for w in tokens if w not in STOP_WORDS]

def compute_tfidf_vectors(docs):
    n = len(docs)
    # 每条文档的词频字典：doc_tf[i] = {word: tf}
    doc_tf = []
    # 每个词的文档频率
    df = defaultdict(int)

    for text in docs:
        tokens = tokenize(text)
        tf_dict = {}
        for w in tokens:
            tf_dict[w] = tf_dict.get(w, 0) + 1
        # 更新文档频率（每个词在当前文档中最多贡献一次）
        for w in tf_dict.keys():
            df[w] += 1
        doc_tf.append(tf_dict)

    # 若所有文档均无有效词
    if not df:
        return [], 0

    V = len(df)
    # 计算 IDF
    idf = {}
    for w, cnt in df.items():
        idf[w] = math.log((1 + n) / (1 + cnt)) + 1

    # 生成 TF-IDF 向量（稀疏表示）
    vectors = []
    for tf_dict in doc_tf:
        vec = {}
        sq_sum = 0.0
        for w, tf in tf_dict.items():
            if w in idf:  # 所有词都应该在idf中
                val = tf * idf[w]
                vec[w] = val
                sq_sum += val * val
        # L2 归一化
        if sq_sum > 0:
            norm = math.sqrt(sq_sum)
            for w in vec:
                vec[w] /= norm
        vectors.append(vec)
    return vectors, n

def similarity_matrix(vectors, n):
    """ 计算余弦相似度矩阵，若vectors为空则返回对角1其余0的矩阵 """
    if not vectors:
        return [[("1.00" if i == j else "0.00") for j in range(n)] for i in range(n)]

    mat = [[""] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j:
                mat[i][j] = "1.00"
                continue
            vi = vectors[i]
            vj = vectors[j]
            # 计算点积
            dot = 0.0
            # 遍历较小的字典以加速
            if len(vi) < len(vj):
                for w, val in vi.items():
                    if w in vj:
                        dot += val * vj[w]
            else:
                for w, val in vj.items():
                    if w in vi:
                        dot += val * vi[w]
            mat[i][j] = f"{dot:.2f}"
    return mat

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    try:
        texts = json.loads(data)
    except json.JSONDecodeError:
        # 简单容错：如果json解析失败则退出
        return
    vectors, n = compute_tfidf_vectors(texts)
    mat = similarity_matrix(vectors, n)
    for row in mat:
        # 直接打印 Python 列表格式
        print(row)

if __name__ == "__main__":
    main()
```

