import java.util.*;
import java.io.*;
import java.util.regex.*;

public class Main {
    // 常见英文停用词集合（与 Python 版本一致）
    private static final Set<String> STOP_WORDS = new HashSet<>(Arrays.asList(
        "a", "an", "the", "is", "are", "was", "were", "be", "been", "being",
        "have", "has", "had", "do", "does", "did", "but", "if", "or", "and",
