        "only", "own", "same", "too", "very", "just", "about", "above",
        "after", "again", "against", "while", "between", "through", "during",
        "before", "below", "up", "down", "out", "off", "over", "under",
        "further", "then", "once", "now", "new", "also", "like"
    ));

    // 分词并去除停用词
    private static List<String> tokenize(String text) {
        List<String> tokens = new ArrayList<>();
        Matcher m = Pattern.compile("[a-zA-Z]+").matcher(text.toLowerCase());
        while (m.find()) {
            String word = m.group();
            if (!STOP_WORDS.contains(word)) {
                tokens.add(word);
            }
        }
        return tokens;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) {
            sb.append(line);
        }
        String input = sb.toString().trim();
        if (input.isEmpty()) {
            return;
        }
        // 简单解析 JSON 数组（假设格式标准，直接按逗号和引号拆分，更健壮可使用 org.json 库，这里用最小实现）
        // 实际题目保证为合法 JSON 数组，此处使用正则提取双引号内的字符串
        List<String> texts = new ArrayList<>();
        Matcher m = Pattern.compile("\"((?:[^\"]|\\\\\")*)\"").matcher(input);
        while (m.find()) {
            texts.add(m.group(1).replace("\\\"", "\""));
        }

        int n = texts.size();
        // 每条文档的词频字典
        List<Map<String, Integer>> docTf = new ArrayList<>();
        // 每个词的文档频率
        Map<String, Integer> df = new HashMap<>();

        for (String text : texts) {
            List<String> tokens = tokenize(text);
            Map<String, Integer> tfMap = new HashMap<>();
            for (String w : tokens) {
                tfMap.put(w, tfMap.getOrDefault(w, 0) + 1);
            }
            // 更新文档频率：每个词在当前文档中只计一次
            for (String w : tfMap.keySet()) {
                df.put(w, df.getOrDefault(w, 0) + 1);
            }
            docTf.add(tfMap);
        }

        if (df.isEmpty()) {
            // 所有文档去停用词后为空
            for (int i = 0; i < n; i++) {
                List<String> row = new ArrayList<>();
                for (int j = 0; j < n; j++) {
                    row.add(i == j ? "1.00" : "0.00");
                }
                System.out.println(row.toString());
            }
            return;
        }

        // 计算 IDF
        Map<String, Double> idf = new HashMap<>();
        for (Map.Entry<String, Integer> e : df.entrySet()) {
            String w = e.getKey();
            int cnt = e.getValue();
            idf.put(w, Math.log((1.0 + n) / (1.0 + cnt)) + 1.0);
        }

        // 生成 TF-IDF 稀疏向量并 L2 归一化
        List<Map<String, Double>> vectors = new ArrayList<>();
        for (Map<String, Integer> tfMap : docTf) {
            Map<String, Double> vec = new HashMap<>();
            double sqSum = 0.0;
            for (Map.Entry<String, Integer> e : tfMap.entrySet()) {
                String w = e.getKey();
                int tf = e.getValue();
                double val = tf * idf.get(w);
                vec.put(w, val);
                sqSum += val * val;
            }
            if (sqSum > 1e-12) {
                double norm = Math.sqrt(sqSum);
                for (Map.Entry<String, Double> e : vec.entrySet()) {
                    e.setValue(e.getValue() / norm);
                }
            }
            vectors.add(vec);
        }

        // 计算相似度矩阵
        String[][] matrix = new String[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) {
                    matrix[i][j] = "1.00";
                    continue;
                }
                Map<String, Double> vi = vectors.get(i);
                Map<String, Double> vj = vectors.get(j);
                double dot = 0.0;
                // 遍历较小的 map
                if (vi.size() < vj.size()) {
                    for (Map.Entry<String, Double> e : vi.entrySet()) {
                        Double val2 = vj.get(e.getKey());
                        if (val2 != null) {
                            dot += e.getValue() * val2;
                        }
                    }
                } else {
                    for (Map.Entry<String, Double> e : vj.entrySet()) {
                        Double val1 = vi.get(e.getKey());
                        if (val1 != null) {
                            dot += e.getValue() * val1;
                        }
                    }
                }
                matrix[i][j] = String.format("%.2f", dot);
            }
        }

        // 输出：每行打印 Python 列表格式，如 ['0.24', '1.00']
        for (int i = 0; i < n; i++) {
            StringBuilder rowStr = new StringBuilder("[");
            for (int j = 0; j < n; j++) {
                if (j > 0) rowStr.append(", ");
                rowStr.append("'").append(matrix[i][j]).append("'");
            }
            rowStr.append("]");
            System.out.println(rowStr.toString());
        }
    }
}
