using namespace std;

// 常见英文停用词集合
const unordered_set<string> STOP_WORDS = {
    "a", "an", "the", "is", "are", "was", "were", "be", "been", "being",
    "have", "has", "had", "do", "does", "did", "but", "if", "or", "and",
    "not", "no", "nor", "so", "as", "at", "by", "for", "from", "of",
