    "after", "again", "against", "while", "between", "through", "during",
    "before", "below", "up", "down", "out", "off", "over", "under",
    "further", "then", "once", "now", "new", "also", "like"
};

vector<string> tokenize(const string& text) {
    vector<string> tokens;
    string lower;
    for (char c : text) lower += tolower(c);
    regex word_regex("[a-zA-Z]+");
    auto words_begin = sregex_iterator(lower.begin(), lower.end(), word_regex);
    auto words_end = sregex_iterator();
    for (auto it = words_begin; it != words_end; ++it) {
        string token = it->str();
        if (STOP_WORDS.find(token) == STOP_WORDS.end()) {
            tokens.push_back(token);
        }
    }
    return tokens;
}

int main() {
    // 读取整个标准输入到字符串
    string input;
    {
        stringstream buffer;
        buffer << cin.rdbuf();
        input = buffer.str();
    }
    // 移除首尾空白
    input.erase(0, input.find_first_not_of(" \n\r\t"));
    if (input.empty()) return 0;

    // 解析 JSON 数组中的字符串（简化版：提取双引号之间的内容，假设输入格式规范）
    vector<string> texts;
    regex str_regex("\"((?:[^\"]|\\\\\")*)\"");
    auto str_begin = sregex_iterator(input.begin(), input.end(), str_regex);
    auto str_end = sregex_iterator();
    for (auto it = str_begin; it != str_end; ++it) {
        string t = (*it)[1].str();
        // 反转义 \" -> "
        size_t pos = 0;
        while ((pos = t.find("\\\"", pos)) != string::npos) {
            t.replace(pos, 2, "\"");
            pos += 1;
        }
        texts.push_back(t);
    }

    int n = texts.size();
    // 每条文档的词频字典（unordered_map<string, int>）
    vector<unordered_map<string, int>> doc_tf(n);
    // 每个词的文档频率
    unordered_map<string, int> df;

    for (int i = 0; i < n; ++i) {
        vector<string> tokens = tokenize(texts[i]);
        unordered_map<string, int> tf_map;
        for (const string& w : tokens) {
            tf_map[w]++;
        }
        for (const auto& p : tf_map) {
            df[p.first]++;  // 每个词在当前文档中只计一次
        }
        doc_tf[i] = tf_map;
    }

    if (df.empty()) {
        // 全空情况：输出对角 1.00 其余 0.00
        for (int i = 0; i < n; ++i) {
            cout << "[";
            for (int j = 0; j < n; ++j) {
                if (j > 0) cout << ", ";
                cout << "'" << (i == j ? "1.00" : "0.00") << "'";
            }
            cout << "]" << endl;
        }
        return 0;
    }

    // 计算 IDF
    unordered_map<string, double> idf;
    for (const auto& e : df) {
        double cnt = e.second;
        idf[e.first] = log((1.0 + n) / (1.0 + cnt)) + 1.0;
    }

    // 生成 TF-IDF 稀疏向量并 L2 归一化
    vector<unordered_map<string, double>> vectors(n);
    for (int i = 0; i < n; ++i) {
        unordered_map<string, double> vec;
        double sq_sum = 0.0;
        for (const auto& p : doc_tf[i]) {
            const string& w = p.first;
            int tf = p.second;
            double val = tf * idf[w];
            vec[w] = val;
            sq_sum += val * val;
        }
        if (sq_sum > 1e-12) {
            double norm = sqrt(sq_sum);
            for (auto& p : vec) {
                p.second /= norm;
            }
        }
        vectors[i] = vec;
    }

    // 计算相似度矩阵并输出（Python 列表格式）
    cout << fixed << setprecision(2);
    for (int i = 0; i < n; ++i) {
        cout << "[";
        for (int j = 0; j < n; ++j) {
            if (j > 0) cout << ", ";
            if (i == j) {
                cout << "'1.00'";
                continue;
            }
            double dot = 0.0;
            const auto& vi = vectors[i];
            const auto& vj = vectors[j];
            // 遍历较小的 map 以减少循环次数
            if (vi.size() < vj.size()) {
                for (const auto& p : vi) {
                    auto it = vj.find(p.first);
                    if (it != vj.end()) {
                        dot += p.second * it->second;
                    }
                }
            } else {
                for (const auto& p : vj) {
                    auto it = vi.find(p.first);
                    if (it != vi.end()) {
                        dot += p.second * it->second;
                    }
                }
            }
            cout << "'" << dot << "'";
        }
        cout << "]" << endl;
    }
    return 0;
}
